# The study specification: one graph per dataset, in the fixed dataset order.
#
# A node is a variable of its dataset. Its type is one of
#   key         subject key, or a record key generated by the record structure
#   rule        calculated by an accepted rule
#   identifier  regenerated (USUBJID, SUBJID, …)
#   sampled     drawn from a model fitted by maximum likelihood
#   blank       not generated
# Cross-dataset inputs are extra nodes: DM variables ("DM.AGE") and record counts of
# datasets generated earlier ("N.AE"). Arrows never point into another dataset.

NODE_TYPES <- c(identifier = "Identifier", sampled = "Sampled", blank = "Not generated")
LEVELS <- c("subject", "visit", "series", "record")
MAX_DEFAULT_LEVELS <- 25

new_study <- function(source) {
  study <- list(source = source, datasets = list(), fits = list())
  for (name in names(source$data)) study$datasets[[name]] <- new_dataset(study, name)
  study
}

# Record structure, variable levels and observation window are read from the source.
# Findings (--TESTCD) and datasets with one record per subject and visit follow a
# schedule; findings add the categorical columns that best separate repeated records
# until records are unique. Otherwise a category that every subject has the same number
# of records of (one DSCAT "DISPOSITION EVENT" each) is planned like a test: its records
# are counted per category, and values are modelled per category. Everything else is a
# count of records per subject.
new_dataset <- function(study, name) {
  x <- study$source$data[[name]]
  dm <- study$source$data$DM
  variables <- names(x)
  prefix <- domain_prefix(name, x)
  unique_share <- function(keys) max(group_index(x, c("USUBJID", keys))) / nrow(x)
  visit <- if ("VISITNUM" %in% variables) "VISITNUM"
  test <- if (paste0(prefix, "TESTCD") %in% variables) paste0(prefix, "TESTCD")
  # Category values with the same number of records in every subject of the dataset.
  subjects <- match(x$USUBJID, unique(x$USUBJID))
  fixed <- do.call(rbind, lapply(variables, function(v) {
    values <- unique(x[[v]])
    if (name == "DM" || !is.character(x[[v]]) || anyNA(values) || !length(values) %in% 2:MAX_DEFAULT_LEVELS) return(NULL)
    records <- vapply(values, function(value) {
      n <- tabulate(subjects[x[[v]] == value], max(subjects))
      if (all(n == n[1])) n[1] else NA_integer_
    }, 0L)
    if (any(!is.na(records))) data.frame(variable = v, value = values, records = records)[!is.na(records), ]
  }))
  structure <- list(type = if (name == "DM") "subject" else "count", keys = character(), visit = NULL, test = NULL,
    by_arm = FALSE, predictors = character(), unique = FALSE)
  if (name != "DM" && is.null(test) && (is.null(visit) || unique_share(visit) < 0.99) && length(fixed)) {
    structure <- list(type = "schedule", keys = fixed$variable[1], visit = NULL, test = fixed$variable[1], by_arm = TRUE,
      predictors = character(), unique = FALSE)
  } else if (name != "DM" && (!is.null(test) || (!is.null(visit) && unique_share(visit) >= 0.99))) {
    keys <- c(visit, test)
    counts <- vapply(x, function(v) length(unique(v)), 0L)
    extra <- variables[counts >= 2 & counts <= MAX_DEFAULT_LEVELS & !vapply(x, inherits, TRUE, "Date")]
    # Supplemental qualifiers folded in from SUPP-- describe records, they never identify them.
    folded <- unlist(lapply(Filter(function(s) identical(s$parent, name), study$source$supp), `[[`, "columns"))
    extra <- setdiff(extra, c("USUBJID", keys, folded))
    while (unique_share(keys) < 0.99 && length(extra)) {
      shares <- vapply(extra, function(e) unique_share(c(keys, e)), 0)
      if (max(shares) <= unique_share(keys)) break
      keys <- c(keys, extra[which.max(shares)])
      extra <- setdiff(extra, keys)
    }
    # A fixed category that the keys (visit aside) determine but the test alone does not (PCSPEC
    # by PCSEQ) is generated with them: drawn per record, its count would vary.
    groups <- function(columns) max(group_index(x, columns))
    combos <- setdiff(keys, visit)
    determined <- Filter(function(v) groups(c(combos, v)) == groups(combos) && groups(c(test, v)) > groups(test),
      setdiff(unique(fixed$variable), keys))
    keys <- c(keys, determined)
    structure <- list(type = "schedule", keys = keys, visit = visit, test = test, by_arm = TRUE,
      predictors = character(), unique = unique_share(keys) >= 0.99)
  }
  # Subject-level variables are constant within subject, visit-level within subject and visit,
  # series-level within a series.
  constant_within <- function(columns) {
    group <- group_index(x, columns)
    repeated <- tabulate(group) > 1
    vapply(x, function(v) {
      distinct <- tabulate(group[!duplicated(group_index(data.frame(group, v), 1:2))], length(repeated))
      any(repeated) && mean(distinct[repeated] == 1) >= 0.99
    }, TRUE)
  }
  links <- subject_links(study$source$data, name, prefix)
  # Series (SDTMIG: --SPID, or the topic variable, links the records of one event or
  # medication recorded at several visits): records collected at the subject's visits (by
  # VISITNUM in SV, or a collection date on an SV date), where a sponsor identifier or topic
  # variable groups them so that each group has each collection visit once, in at least 95%
  # of groups, and at least 10% of groups have several records. Of these the grouping with
  # the most variables constant within a group.
  if (identical(structure$type, "count")) {
    collection <- if (isTRUE(links$visits >= SHARE_TO_PROPOSE) && !is.null(visit)) "VISITNUM" else
      intersect(paste0(prefix, "DTC"), links$collected)[1]
    candidates <- if (!is.na(collection)) intersect(paste0(prefix, c("SPID", "TRT", "TERM", "DECOD")), variables)
    once <- vapply(candidates, function(k) {
      group <- group_index(x, c("USUBJID", k))
      size <- tabulate(group)
      distinct <- tabulate(group[!duplicated(group_index(x, c("USUBJID", k, collection)))], length(size))
      if (mean(distinct == size) >= 0.95 && mean(size > 1) >= 0.1) sum(constant_within(c("USUBJID", k))) else NA_real_
    }, 0)
    if (any(!is.na(once))) {
      sv <- study$source$data[[VISIT_HUB]]
      date <- main_date(VISIT_HUB, names(sv))
      schedule <- if (collection == "VISITNUM") x$VISITNUM else
        sv$VISITNUM[match(paste(x$USUBJID, as.numeric(x[[collection]])), paste(sv$USUBJID, as.numeric(sv[[date]])))]
      structure <- list(type = "series", keys = collection, visit = NULL, test = NULL, by_arm = FALSE, predictors = character(),
        unique = FALSE, series = names(which.max(once)), schedule = sort(unique(stats::na.omit(schedule))),
        date = if (collection == "VISITNUM") paste0(VISIT_HUB, ".", date) else collection)
    }
  }
  levels <- rep("record", length(variables))
  if (!is.null(structure$visit)) levels[constant_within(c("USUBJID", structure$visit))] <- "visit"
  if (!is.null(structure$series)) levels[constant_within(c("USUBJID", structure$series))] <- "series"
  levels[name == "DM" | constant_within("USUBJID")] <- "subject"
  # The observation window is the latest subject date (a DM date, or the first or last date
  # in a column of an earlier dataset) that 99% of the records' dates follow and the
  # earliest that they precede, among those known for 90% of the records.
  window <- list(start = "", end = "")
  dates <- Filter(function(v) inherits(v, "Date"), x)
  if (name != "DM" && length(dates)) {
    bounds <- list(start = do.call(pmin, c(dates, na.rm = TRUE)), end = do.call(pmax, c(dates, na.rm = TRUE)))
    subjects <- subject_inputs(study, study$source$data, name)
    reference <- Filter(function(v) inherits(v, "Date"), subjects[match(x$USUBJID, subjects$USUBJID), -1, drop = FALSE])
    for (side in names(window)) {
      sign <- if (side == "start") 1 else -1
      dated <- !is.na(bounds[[side]])
      holds <- vapply(reference, function(r) mean(!is.na(r[dated])) >= 0.9 &&
        mean(sign * (bounds[[side]] - r) >= 0, na.rm = TRUE) >= 0.99, TRUE)
      tightness <- vapply(reference, function(r) sign * as.numeric(stats::median(r, na.rm = TRUE)), 0)
      if (any(holds)) window[[side]] <- names(reference)[holds][which.max(tightness[holds])]
    }
  }
  # Spans: in 99% of subjects, their first date in a column is on or before a subject date
  # (known for SHARE_TO_PROPOSE of them), or their last on or after it, where the records
  # alone do not keep that order. The tightest such date per column and side; only for
  # records counted per subject or in series.
  spans <- NULL
  if (name != "DM" && length(dates) && structure$type %in% c("count", "series")) for (v in names(dates)) for (side in c("first", "last")) {
    sign <- if (side == "first") 1 else -1
    y <- as.numeric(x[[v]])
    pick <- tapply(y, x$USUBJID, function(z) if (all(is.na(z))) NA else if (side == "first") min(z, na.rm = TRUE) else max(z, na.rm = TRUE))
    holds <- vapply(reference, function(r) {
      at <- tapply(as.numeric(r), x$USUBJID, `[`, 1)[names(pick)]
      known <- !is.na(pick) & !is.na(at)
      sum(known) >= 10 && mean(known[!is.na(pick)]) >= SHARE_TO_PROPOSE &&
        mean(sign * (as.numeric(r) - y) >= 0, na.rm = TRUE) < 0.99 && mean(sign * (at - pick)[known] >= 0) >= 0.99
    }, TRUE)
    tightness <- vapply(reference, function(r) -sign * as.numeric(stats::median(r, na.rm = TRUE)), 0)
    if (any(holds)) spans <- rbind(spans, data.frame(column = v, node = names(reference)[holds][which.max(tightness[holds])], side = side,
      stringsAsFactors = FALSE))
  }
  pins <- Filter(function(p) p$dataset == name, subject_pins(study$source$data))
  links$spans <- spans
  links$milestones <- setdiff(links$milestones, names(pins))
  links$milestone_visits <- links$milestone_visits[intersect(names(links$milestone_visits), links$milestones)]
  structure$sv <- isTRUE(links$visits >= SHARE_TO_PROPOSE) && "VISITNUM" %in% variables
  # SV's visits are those the subject reaches within its window, entry to end of participation.
  if (name == VISIT_HUB && identical(structure$visit, "VISITNUM") && all(nzchar(unlist(window))))
    structure$reach <- c(date = main_date(prefix, variables), unlist(window))
  node <- list(type = NA_character_, predictors = character(), model = "auto", prev = FALSE, vary = FALSE)
  nodes <- setNames(rep(list(node), length(variables)), variables)
  for (v in intersect(c("USUBJID", structure$keys), variables)) nodes[[v]]$type <- if (name == "DM") "identifier" else "key"
  # A sponsor identifier of a series is numbered per subject with the series.
  if (endsWith(structure$series %||% "", "SPID")) nodes[[structure$series]]$type <- "key"
  # VISITNUM identifies a visit: its values are categories, not a scale.
  if ("VISITNUM" %in% variables) nodes$VISITNUM$model <- "categories"
  list(name = name, prefix = prefix, class = domain_class(name, x), variables = variables,
    labels = study$source$labels[[name]], structure = structure,
    levels = setNames(levels, variables), kinds = vapply(x, value_kind, ""), inputs = character(), rules = list(),
    nodes = nodes, order = character(), include = TRUE, window = window, fixed = fixed, links = links, pins = pins)
}

# ---- Subject timeline -------------------------------------------------------------------

# A subject's records hang on two hubs: DM, one record per subject, and SV, one record per
# visit attended. DM's dates are the subject's timeline: they are drawn first and never
# changed, and every later dataset is fitted to them. The timeline is a DAG with edges
#   order      a DM date on or after another (DMDTC ≤ RFSTDTC ≤ RFXENDTC ≤ RFENDTC ≤ RFPENDTC)
#   milestone  a DM date is the date of one of the subject's SV visits
#   pin        a DM date is the first or last date of a dataset column (RFSTDTC, first EXSTDTC)
#   bound      a record date on or after, or on or before, a DM date, the subject's first or
#              last date in a column of an earlier dataset, its SV visit's date or another
#              date of the record
#   visit      a dataset's visits are visits the subject attended in SV
#   on visit   a dataset date within its SV visit's dates
#   collected  a dataset date (--DTC, the collection date) is one of the subject's SV dates
#   span       the subject's first date in a column on or before a subject date (a DM date, or
#              a first or last date of an earlier dataset), or their last on or after it
# Each is an SDTM convention that a study uses when it holds on its source: pins, milestones,
# visits, on-visit and collected dates for SHARE_TO_PROPOSE of subjects or records, orders and bounds
# for 99% of records, as the observation window. Every edge starts in DM or a dataset drawn
# earlier, so drawing the datasets in order draws the DAG; `timeline_edges()` lists the
# edges and the coherence checks test each one.
VISIT_HUB <- "SV"

# Pins, from SDTMIG's definitions of DM's dates, in order of preference per DM date.
# Reference dates keep DM's presence (a screen failure has none); the death date is present
# exactly when DS records a death.
TIMELINE_PINS <- utils::read.table(header = TRUE, stringsAsFactors = FALSE, text = "
  target    dataset  column   pick   where                            all
  RFSTDTC   EX       EXSTDTC  first  -                                FALSE
  RFSTDTC   SV       SVSTDTC  first  -                                FALSE
  RFXSTDTC  EX       EXSTDTC  first  -                                FALSE
  RFXENDTC  EX       EXENDTC  last   -                                FALSE
  RFENDTC   EX       EXENDTC  last   -                                FALSE
  RFENDTC   DS       DSSTDTC  last   'DSCAT == \"DISPOSITION EVENT\"'  FALSE
  RFENDTC   SV       SVENDTC  last   -                                FALSE
  RFPENDTC  DS       DSSTDTC  last   'DSCAT == \"DISPOSITION EVENT\"'  FALSE
  RFPENDTC  SV       SVENDTC  last   -                                FALSE
  RFICDTC   DS       DSSTDTC  first  'DSDECOD == \"INFORMED CONSENT OBTAINED\"'  FALSE
  DMDTC     SV       SVSTDTC  first  -                                FALSE
  DTHDTC    DS       DSSTDTC  first  'DSDECOD == \"DEATH\"'             TRUE
")

main_date <- function(prefix, columns) intersect(paste0(prefix, c("STDTC", "DTC")), columns)[1]

# Each subject's first or last date of the pinned column, among the pin's records.
pin_value <- function(pin, data, subjects) {
  x <- data[[pin$dataset]]
  if (pin$where != "-") x <- x[which(eval(parse(text = pin$where), x)), , drop = FALSE]
  date <- x[[pin$column]]
  keep <- !is.na(date)
  pick <- if (pin$pick == "first") min else max
  value <- tapply(as.numeric(date[keep]), x$USUBJID[keep], pick)
  as.Date(unname(value[subjects]), origin = "1970-01-01")
}

pin_label <- function(p) sprintf("%s %s%s = DM.%s", p$pick, p$column, if (p$where == "-") "" else paste(" where", p$where), p$target)

# The first pin per DM date that holds on source.
subject_pins <- function(data) {
  dm <- data$DM
  chosen <- list()
  for (i in seq_len(nrow(TIMELINE_PINS))) {
    p <- as.list(TIMELINE_PINS[i, ])
    x <- data[[p$dataset]]
    if (p$target %in% names(chosen) || !inherits(dm[[p$target]], "Date") || !inherits(x[[p$column]], "Date")) next
    if (p$where != "-" && !all(all.vars(parse(text = p$where)) %in% names(x))) next
    value <- pin_value(p, data, dm$USUBJID)
    checked <- !is.na(dm[[p$target]]) | (p$all & !is.na(value))
    p$share <- mean(same_value(value[checked], dm[[p$target]][checked]))
    if (sum(checked) >= 2 && p$share >= SHARE_TO_PROPOSE) chosen[[p$target]] <- c(p, if (p$all) list(state = pin_state(p, x)))
  }
  chosen
}

# A pin that holds for every subject makes its records a state: a subject has one exactly
# when DM has the date (a death record when DTHDTC is known). The state is any column whose
# values on the pin's source records occur on no other record, the condition's own first,
# with the most common value of each text column on those records.
pin_state <- function(pin, x) {
  rows <- eval(parse(text = pin$where), x) %in% TRUE
  columns <- list()
  for (v in unique(c(all.vars(parse(text = pin$where)), names(x)))) {
    levels <- unique(x[[v]][rows])
    if (is.character(x[[v]]) && !anyNA(levels) && identical(x[[v]] %in% levels, rows)) columns[[v]] <- levels
  }
  usual <- vapply(Filter(is.character, x[rows, , drop = FALSE]), function(v) names(which.max(table(v))) %||% NA_character_, "")
  list(columns = columns, usual = usual)
}

# The edges of the timeline DAG (see above), from the specification and fits: `to` keeps
# `relation` to `from`. Nodes are DM.<VAR>, SV.<VAR> (the record's visit), <DATASET>.<VAR> and,
# for datasets generated earlier, <DATASET>.<VAR>.FIRST and .LAST (the subject's first and last).
timeline_edges <- function(study) {
  included <- names(study$datasets)[vapply(study$datasets, `[[`, TRUE, "include")]
  edges <- list()
  add <- function(kind, from, to, relation, where = "-", all = FALSE)
    edges[[length(edges) + 1]] <<- data.frame(kind = kind, from = from, to = to, relation = relation, where = where, all = all,
      stringsAsFactors = FALSE)
  sv <- study$datasets[[VISIT_HUB]]
  for (name in included) {
    ds <- study$datasets[[name]]
    own <- function(v) if (grepl("^(DM|N|SV)\\.|\\.(FIRST|LAST)$", v) && !startsWith(v, "SERIES.")) v else paste0(name, ".", v)
    dates <- ds$variables[ds$kinds[ds$variables] == "date" & node_types(ds)[ds$variables] %in% c("rule", "sampled")]
    # Fitted bounds of sampled dates; in DM these are the order of the reference dates.
    for (v in intersect(dates, variables_of_type(ds, "sampled"))) {
      fit <- study$fits[[name]]$nodes[[v]]
      for (a in fit$after) add(if (name == "DM") "order" else "bound", own(a), own(v), ">=")
      for (b in fit$before) add(if (name == "DM") "order" else "bound", own(b), own(v), "<=")
    }
    if (name != "DM") for (v in dates) {
      if (nzchar(ds$window$start)) add("bound", ds$window$start, own(v), ">=")
      if (nzchar(ds$window$end)) add("bound", ds$window$end, own(v), "<=")
    }
    for (p in ds$pins) add("pin", paste0("DM.", p$target), own(p$column), paste("=", p$pick), p$where, p$all)
    for (m in ds$links$milestones) add("milestone", paste0("DM.", m), own(main_date(ds$prefix, ds$variables)), "in")
    if (isTRUE(ds$structure$sv) && isTRUE(sv$include)) {
      add("visit", paste0(VISIT_HUB, ".VISITNUM"), own("VISITNUM"), "in")
      for (v in ds$links$on_visit) add("on visit", paste0(VISIT_HUB, ".", main_date(VISIT_HUB, sv$variables)), own(v), "within")
    }
    if (isTRUE(sv$include)) for (v in ds$links$collected)
      add("collected", paste0(VISIT_HUB, ".", main_date(VISIT_HUB, sv$variables)), own(v), "in")
    for (i in seq_len(NROW(ds$links$spans))) with(ds$links$spans[i, ],
      add("span", node, own(column), if (side == "first") "first <=" else "last >="))
  }
  edges <- do.call(rbind, edges)
  if (is.null(edges)) return(NULL)
  # Each order or bound once, as both dates' fits find it.
  ordered <- edges$kind %in% c("order", "bound")
  lo <- ifelse(edges$relation == "<=", edges$to, edges$from)
  hi <- ifelse(edges$relation == "<=", edges$from, edges$to)
  edges <- edges[!(ordered & duplicated(paste(ordered, lo, hi))), , drop = FALSE]
  rownames(edges) <- NULL
  edges
}

edge_dataset <- function(node) sub("\\..*$", "", node)

# SV's dates as SV.<VAR>, one row per subject and visit.
visit_frame <- function(data) {
  sv <- data[[VISIT_HUB]]
  if (is.null(sv) || !"VISITNUM" %in% names(sv)) return(NULL)
  sv <- sv[!duplicated(visit_keys(sv)), , drop = FALSE]
  dates <- Filter(function(v) inherits(v, "Date"), sv)
  out <- data.frame(.key = visit_keys(sv), dates, stringsAsFactors = FALSE)
  names(out)[-1] <- paste0(VISIT_HUB, ".", names(dates))
  out
}

visit_keys <- function(x) paste(x$USUBJID, format_value(x$VISITNUM), sep = "\r")

# Records read their SV visit's dates.
join_visits <- function(frame, data) {
  visits <- visit_frame(data)
  frame[names(visits)[-1]] <- visits[match(visit_keys(frame), visits$.key), -1, drop = FALSE]
  frame
}

# The visits each subject attended in SV. A dataset with dates on its visit's date only has
# the visits inside its observation window.
allowed_visits <- function(data, ds) {
  sv <- data[[VISIT_HUB]]
  if (is.null(sv) || !"VISITNUM" %in% names(sv)) return(NULL)
  date <- sv[[main_date(VISIT_HUB, names(sv))]]
  keep <- rep(TRUE, nrow(sv))
  if (length(ds$links$on_visit)) for (side in c("start", "end")) {
    if (!nzchar(ds$window[[side]])) next
    bound <- subject_date(data, ds$window[[side]], sv$USUBJID)
    if (is.null(bound)) next
    gap <- as.numeric(date) - as.numeric(bound)
    keep <- keep & (is.na(gap) | if (side == "start") gap >= 0 else gap <= 0)
  }
  unique(data.frame(USUBJID = sv$USUBJID[keep], visit = format_value(sv$VISITNUM[keep]), date = date[keep], stringsAsFactors = FALSE))
}

# A drawn visit the subject did not attend in SV is redrawn among their allowed visits, as
# often as each is drawn overall (the visit model given the visits attended); a subject whose
# allowed visits are never drawn takes the nearest.
attended_visit <- function(x, data, ds) {
  visits <- allowed_visits(data, ds)
  visit <- x$VISITNUM
  away <- which(!is.na(visit) & !visit_keys(x) %in% paste(visits$USUBJID, visits$visit, sep = "\r"))
  own <- split(as.numeric(visits$visit), visits$USUBJID)
  drawn <- table(format_value(visit))
  for (i in away) {
    v <- own[[x$USUBJID[i]]]
    if (!length(v)) next
    w <- as.numeric(drawn[format_value(v)])
    w[is.na(w)] <- 0
    visit[i] <- if (sum(w) > 0) v[sample.int(length(v), 1, prob = w)] else v[which.min(abs(v - as.numeric(visit[i])))]
  }
  visit
}

# The subject's visit on each date, or else their last visit before it.
visit_on <- function(data, ds, subjects, dates, current) {
  visits <- allowed_visits(data, ds)
  vapply(seq_along(subjects), function(i) {
    own <- visits[visits$USUBJID == subjects[i] & !is.na(visits$date), , drop = FALSE]
    gap <- as.numeric(own$date) - dates[i]
    same <- as.numeric(own$visit[gap == 0])
    if (length(same)) return(if (as.numeric(current[i]) %in% same) as.numeric(current[i]) else max(same))
    if (any(gap < 0)) return(as.numeric(own$visit[gap < 0][which.max(gap[gap < 0])]))
    as.numeric(current[i])
  }, 0)
}

# The visits each subject can have, for datasets whose records are planned by visit or
# recorded in series.
subject_visits <- function(data, ds) {
  if (!identical(ds$structure$type, "series") && (!isTRUE(ds$structure$sv) || !identical(ds$structure$visit, "VISITNUM"))) return(NULL)
  allowed_visits(data, ds)
}

# What the source shows for one dataset: the share of records at a visit the subject has
# in SV, the dates within that visit's SV dates, the share of fatal outcomes (--OUT =
# "FATAL") in subjects with a death date (the fatal records' state, see `pin_state()`), and for SV the DM dates that are a visit's date.
subject_links <- function(data, name, prefix) {
  x <- data[[name]]
  links <- list()
  visits <- visit_frame(data)
  if (name != VISIT_HUB && "VISITNUM" %in% names(x) && !is.null(visits)) {
    row <- match(visit_keys(x), visits$.key)
    links$visits <- mean(!is.na(row))
    start <- visits[[paste0(VISIT_HUB, ".SVSTDTC")]][row]
    end <- visits[[paste0(VISIT_HUB, ".SVENDTC")]][row] %||% start
    dates <- names(Filter(function(v) inherits(v, "Date"), x))
    on <- vapply(dates, function(v) isTRUE(mean(x[[v]] >= start & x[[v]] <= end, na.rm = TRUE) >= SHARE_TO_PROPOSE), TRUE)
    links$on_visit <- dates[on]
  }
  sv <- data[[VISIT_HUB]]
  if (name != VISIT_HUB && name != "DM" && !is.null(sv)) {
    days <- paste(sv$USUBJID, as.numeric(sv[[main_date(VISIT_HUB, names(sv))]]))
    dates <- setdiff(names(Filter(function(v) inherits(v, "Date"), x)), links$on_visit)
    held <- vapply(dates, function(v) isTRUE(mean((paste(x$USUBJID, as.numeric(x[[v]])) %in% days)[!is.na(x[[v]])]) >= SHARE_TO_PROPOSE), TRUE)
    links$collected <- dates[held]
  }
  if (name == VISIT_HUB && !is.null(visits)) {
    date <- as.numeric(x[[main_date(prefix, names(x))]])
    on <- vapply(Filter(function(v) inherits(v, "Date"), data$DM), function(m) {
      m <- as.numeric(m)[match(x$USUBJID, data$DM$USUBJID)]
      hit <- tapply(!is.na(date) & date == m, x$USUBJID, any)[!is.na(tapply(m, x$USUBJID, `[`, 1))]
      length(hit) >= 2 && mean(hit) >= SHARE_TO_PROPOSE
    }, TRUE)
    links$milestones <- names(on)[on]
    # The visit a milestone falls on, when one visit carries it in most subjects.
    links$milestone_visits <- unlist(lapply(setNames(links$milestones, links$milestones), function(m) {
      m <- as.numeric(data$DM[[m]])[match(x$USUBJID, data$DM$USUBJID)]
      visit <- format_value(x$VISITNUM[which(date == m)])
      top <- names(which.max(table(visit)))
      if (length(top) && mean(visit == top) >= SHARE_TO_PROPOSE) top
    }))
  }
  outcome <- x[[paste0(prefix, "OUT")]]
  dead <- data$DM$USUBJID[!is.na(data$DM$DTHDTC %||% NA)]
  if (!is.null(outcome) && any(outcome %in% "FATAL")) {
    links$fatal <- mean(x$USUBJID[outcome %in% "FATAL"] %in% dead)
    # Fatal records as a state of the subjects with a death date, and whether every one has such a record.
    links$fatal_state <- pin_state(list(where = sprintf('%sOUT == "FATAL"', prefix)), x)
    links$fatal_all <- length(dead) >= 2 && mean(dead %in% x$USUBJID[outcome %in% "FATAL"]) >= SHARE_TO_PROPOSE
  }
  links
}

# ---- Frames ---------------------------------------------------------------------------

# A dataset's records with every DM variable joined as DM.<VAR> and record counts of
# earlier datasets as N.<DATASET>. The record structure travels as an attribute.
dataset_frame <- function(study, name, data = study$source$data) {
  x <- data[[name]]
  if (name != "DM") {
    subjects <- subject_inputs(study, data, name)
    x <- cbind(x, subjects[match(x$USUBJID, subjects$USUBJID), -1, drop = FALSE])
    visits <- if (isTRUE(study$datasets[[name]]$structure$sv)) visit_frame(data)
    if (!is.null(visits)) x <- cbind(x, visits[match(visit_keys(x), visits$.key), -1, drop = FALSE])
    if (identical(study$datasets[[name]]$structure$type, "series")) x <- series_frame(x, study$datasets[[name]]$structure)
    rownames(x) <- NULL
  }
  attr(x, "structure") <- study$datasets[[name]]$structure
  x
}

# A series' records carry its first and last collection date and whether it is still
# recorded at the subject's last collection in the dataset (SERIES.FIRST, .LAST, .ONGOING):
# series-level inputs, as an event's start and end bound where it is recorded.
SERIES_INPUTS <- paste0("SERIES.", c("FIRST", "LAST", "ONGOING"))

series_frame <- function(x, s) {
  if (is.null(x$.series)) x$.series <- group_index(x, c("USUBJID", s$series))
  date <- as.numeric(x[[s$date]])
  pick <- function(group, f) stats::ave(date, group, FUN = function(v) if (all(is.na(v))) NA else f(v, na.rm = TRUE))
  last <- pick(x$.series, max)
  x$SERIES.FIRST <- as.Date(pick(x$.series, min), origin = "1970-01-01")
  x$SERIES.LAST <- as.Date(last, origin = "1970-01-01")
  x$SERIES.ONGOING <- as.numeric(!is.na(last) & last == pick(x$USUBJID, max))
  x
}

subject_inputs <- function(study, data, name) {
  dm <- data$DM
  subjects <- data.frame(USUBJID = dm$USUBJID, stringsAsFactors = FALSE)
  for (v in setdiff(names(dm), "USUBJID")) subjects[[paste0("DM.", v)]] <- dm[[v]]
  for (d in intersect(earlier_datasets(study, name), names(data)))
    subjects[[paste0("N.", d)]] <- as.numeric(tabulate(match(data[[d]]$USUBJID, dm$USUBJID), nrow(dm)))
  for (node in subject_date_nodes(study, name, data)) subjects[[node]] <- subject_date(data, node, dm$USUBJID)
  subjects
}

# A dataset not yet in the study (while it is being read) comes after those that are.
earlier_datasets <- function(study, name) {
  datasets <- names(study$datasets)
  setdiff(datasets[seq_len(match(name, datasets, nomatch = length(datasets) + 1) - 1)], "DM")
}

# The subject's first and last date in each date column of an earlier dataset,
# <DATASET>.<VAR>.FIRST and .LAST: timeline nodes for later datasets.
subject_date_nodes <- function(study, name, data = study$source$data) {
  as.character(unlist(lapply(intersect(earlier_datasets(study, name), names(data)), function(d) {
    dates <- names(Filter(function(v) inherits(v, "Date"), data[[d]]))
    c(paste0(d, ".", dates, ".FIRST"), paste0(d, ".", dates, ".LAST"))
  })))
}

# A subject-level timeline node, DM.<VAR> or <DATASET>.<VAR>.FIRST/.LAST, for `subjects`.
subject_date <- function(data, node, subjects) {
  part <- strsplit(node, ".", fixed = TRUE)[[1]]
  if (part[1] == "DM") return(data$DM[[part[2]]][match(subjects, data$DM$USUBJID)])
  x <- data[[part[1]]]
  if (is.null(x[[part[2]]])) return(NULL)
  keep <- !is.na(x[[part[2]]])
  pick <- tapply(as.numeric(x[[part[2]]][keep]), x$USUBJID[keep], if (part[3] == "FIRST") min else max)
  as.Date(unname(pick[subjects]), origin = "1970-01-01")
}

input_choices <- function(study, name) {
  if (name == "DM") return(character())
  generated <- variables_of_type(study$datasets$DM, c("rule", "sampled", "identifier"))
  earlier <- earlier_datasets(study, name)
  counts <- earlier[vapply(study$datasets[earlier], `[[`, TRUE, "include")]
  sv <- study$datasets[[VISIT_HUB]]
  visits <- if (isTRUE(study$datasets[[name]]$structure$sv) && isTRUE(sv$include)) paste0(VISIT_HUB, ".", sv$variables[sv$kinds[sv$variables] == "date"])
  c(paste0("DM.", setdiff(generated, "USUBJID")), if (length(counts)) paste0("N.", counts), visits,
    if (identical(study$datasets[[name]]$structure$type, "series")) SERIES_INPUTS)
}

# ---- Rules and node types --------------------------------------------------------------

# Rules are found, every other variable gets its suggested type (rule targets too, for
# when their rule is rejected) and the starting graph is built, so a dataset starts out
# complete. Datasets are prepared in order: later starting graphs use DM's arm.
discover_dataset <- function(study, name) {
  ds <- study$datasets[[name]]
  ds$rules <- discover_rules(discovery_frame(study, name), setdiff(ds$variables, c("USUBJID", ds$structure$keys)), ds$prefix)
  x <- study$source$data[[name]]
  for (v in ds$variables[is.na(vapply(ds$nodes, `[[`, "", "type"))]) ds$nodes[[v]]$type <- suggest_type(ds, x, v)
  study$datasets[[name]] <- starting_graph(study, ds)
  study
}

# Rules are searched among the dataset's own variables and DM's. Record counts of other
# datasets (N.*) would add one candidate key per earlier dataset, so the search would
# grow with the square of the number of datasets.
discovery_frame <- function(study, name) {
  frame <- dataset_frame(study, name)
  structure <- attr(frame, "structure")
  frame <- frame[!grepl("^N\\.|\\.(FIRST|LAST)$|^SERIES\\.|^\\.series$", names(frame))]
  attr(frame, "structure") <- structure
  frame
}

node_type <- function(ds, variable) {
  rule <- ds$rules[[variable]]
  if (!is.null(rule) && rule$status == "accepted") return("rule")
  ds$nodes[[variable]]$type %||% NA_character_
}

node_types <- function(ds) vapply(ds$variables, node_type, "", ds = ds)

variables_of_type <- function(ds, types) ds$variables[node_types(ds) %in% types]

accepted_rules <- function(ds) Filter(function(r) r$status == "accepted", ds$rules)

remaining_variables <- function(ds) ds$variables[!node_types(ds) %in% c("key", "rule")]

generated_variables <- function(ds) variables_of_type(ds, c("key", "rule", "sampled", "identifier"))

# Starting types, which the user can change. Text that is (nearly) unique per record is an
# identifier; free text is not generated unless an accepted rule needs it.
suggest_type <- function(ds, x, variable) {
  v <- x[[variable]]
  observed <- v[!is.na(v)]
  n_values <- length(unique(observed))
  if (variable %in% unlist(lapply(accepted_rules(ds), rule_columns))) return("sampled")
  if (!length(observed)) return("blank")
  if (is.character(v) && n_values >= 10 && n_values >= 0.99 * length(observed)) return("identifier")
  if (is.character(v) && n_values > 50 && n_values > 0.3 * length(observed)) return("blank")
  "sampled"
}

arm_variable <- function(dm) {
  arms <- intersect(c("ARMCD", "ARM"), dm$variables)
  arms[arms %in% variables_of_type(dm, "sampled")][1]
}

# Records follow the treatment actually received when DM generates it.
treatment_variable <- function(dm) {
  actual <- intersect(c("ACTARMCD", "ACTARM"), variables_of_type(dm, c("sampled", "rule")))
  if (length(actual)) actual[1] else arm_variable(dm)
}

# Nodes a node's value depends on. Inputs (DM.*, N.*) and keys have no parents here;
# SV inputs (SV.*) are read at the record's visit.
node_parents <- function(ds, variable) {
  parents <- switch(node_type(ds, variable), sampled = ds$nodes[[variable]]$predictors,
    rule = rule_columns(ds$rules[[variable]]), character())
  if (any(startsWith(parents, paste0(VISIT_HUB, "."))) && variable != "VISITNUM") parents <- union(parents, "VISITNUM")
  parents
}

# `start` and every node reachable from it by repeatedly following `step`.
reachable <- function(start, step) {
  found <- start
  frontier <- start
  while (length(frontier)) {
    frontier <- setdiff(step(frontier), found)
    found <- union(found, frontier)
  }
  found
}

# `nodes` and every variable calculated or sampled from them.
descendants <- function(ds, nodes) reachable(nodes, function(n) Filter(function(v) any(n %in% node_parents(ds, v)), ds$variables))

generation_order <- function(ds) {
  nodes <- generated_variables(ds)
  parents <- lapply(setNames(nodes, nodes), function(v) intersect(node_parents(ds, v), nodes))
  order <- character()
  while (length(order) < length(nodes)) {
    ready <- setdiff(nodes[vapply(parents, function(p) all(p %in% order), TRUE)], order)
    if (!length(ready)) stop("Cycle among ", paste(setdiff(nodes, order), collapse = ", "))
    # Rules first, so that sampled dates are bounded by the dates rules give.
    order <- c(order, ready[order(node_types(ds)[ready] != "rule")])
  }
  order
}

# ---- Starting graph ---------------------------------------------------------------------

# The ordering is the given one, completed by the arm, then the remaining sampled
# variables in column order with dates last, collection dates after the others.
# Synthpop-style: each sampled node uses the dataset's inputs (by default the arm) and
# every earlier node in the ordering at its level or coarser that carries information:
# numbers, or codes with few levels. In DM the arm is not a predictor of baseline values.
# A date is modelled as a gap from the DM or earlier date with the smallest spread of gaps.
starting_graph <- function(study, ds, order = character()) {
  is_dm <- ds$name == "DM"
  arm <- if (is_dm) arm_variable(ds) else treatment_variable(study$datasets$DM)
  sampled <- variables_of_type(ds, "sampled")
  dates <- sampled[ds$kinds[sampled] == "date"]
  # A collection date (--DTC on a visit date) follows the event dates it is collected after.
  dates <- c(setdiff(dates, ds$links$collected), intersect(dates, ds$links$collected))
  order <- unique(c(intersect(order, sampled), if (is_dm) stats::na.omit(arm), setdiff(sampled, dates), dates))
  choices <- input_choices(study, ds$name)
  death <- if (any(paste0(ds$prefix, c("OUT", "SDTH")) %in% ds$variables) || ds$name == "DS") "DTHFL"
  if (!is_dm && !length(ds$inputs)) ds$inputs <- intersect(c(paste0("DM.", c(arm, death)), "SERIES.ONGOING"), choices)
  frame <- dataset_frame(study, ds$name)
  kinds <- vapply(frame, value_kind, "")
  few <- vapply(frame, function(v) length(unique(v)), 0L) <= MAX_DEFAULT_LEVELS
  informative <- names(frame)[kinds == "numeric" | (kinds != "date" & few)]
  s <- ds$structure
  for (i in seq_along(order)) {
    v <- order[i]
    earlier <- order[seq_len(i - 1)]
    level <- match(ds$levels[[v]], LEVELS)
    usable <- earlier[match(ds$levels[earlier], LEVELS) <= level & earlier %in% informative]
    if (is_dm && kinds[[v]] != "date") usable <- setdiff(usable, arm)
    predictors <- c(intersect(ds$inputs, informative), usable, if (level >= 2) s$visit)
    dates <- if (kinds[[v]] == "date") c(choices, earlier)[kinds[c(choices, earlier)] %in% "date"]
    spread <- vapply(dates, function(d) {
      gap <- as.numeric(frame[[v]] - frame[[d]])
      if (sum(!is.na(gap)) < max(2, 0.5 * sum(!is.na(frame[[v]])))) Inf else stats::mad(gap, na.rm = TRUE) + stats::sd(gap, na.rm = TRUE)
    }, 0)
    anchor <- if (any(is.finite(spread))) dates[which.min(spread)]
    ds$nodes[[v]]$predictors <- unique(c(anchor, predictors))
    ds$nodes[[v]]$prev <- !is.null(s$visit) && !is.null(s$test) && ds$levels[[v]] == "record" && kinds[[v]] == "numeric"
  }
  if (s$type %in% c("count", "series")) ds$structure$predictors <- intersect(paste0("DM.", arm), ds$inputs)
  ds$order <- order
  ds
}

# ---- Checks ----------------------------------------------------------------------------

# One row of a check table, for specification and coherence checks alike: a check
# passes when it finds no problems.
check_row <- function(dataset, check, problems = character()) {
  shown <- paste(utils::head(problems, 5), collapse = "; ")
  if (length(problems) > 5) shown <- sprintf("%s (+%d more)", shown, length(problems) - 5)
  data.frame(Dataset = dataset, Check = check, Status = if (length(problems)) "failed" else "ok",
    Problems = shown, stringsAsFactors = FALSE)
}

check_study <- function(study) {
  included <- names(study$datasets)[vapply(study$datasets, `[[`, TRUE, "include")]
  edges <- timeline_edges(study) %||% data.frame(from = character(), to = character())
  back <- edges[match(edge_dataset(edges$from), names(study$datasets)) > match(edge_dataset(edges$to), names(study$datasets)) |
    !edge_dataset(edges$from) %in% c("N", included), , drop = FALSE]
  rows <- list(check_row("Study", "DM is generated first and provides every subject", if (!"DM" %in% included) "DM is excluded"),
    check_row("Study", "Every timeline edge starts in DM or an earlier generated dataset", paste(back$from, "→", back$to)))
  do.call(rbind, c(rows, lapply(included, check_dataset, study = study)))
}

# One dataset's checks. They read only the dataset, DM's graph and which earlier datasets
# are generated, so a dataset is checked where it is built.
check_dataset <- function(study, name) {
  ds <- study$datasets[[name]]
  inputs <- input_choices(study, name)
  available <- c(generated_variables(ds), inputs)
  sampled <- variables_of_type(ds, "sampled")
  unavailable <- lapply(ds$variables, function(v) setdiff(node_parents(ds, v), available))
  finer <- lapply(sampled, function(v) {
    p <- intersect(ds$nodes[[v]]$predictors, ds$variables)
    p[match(ds$levels[p], LEVELS) > match(ds$levels[[v]], LEVELS)]
  })
  rbind(
    if (name == "DM") check_row("DM", "A treatment arm variable (ARMCD or ARM) is sampled from the allocation ratio",
      if (is.na(arm_variable(ds))) "no arm"),
    check_row(name, "Every variable has a type", ds$variables[is.na(node_types(ds))]),
    check_row(name, "Every rule input and predictor is generated before use",
      paste(ds$variables, "needs", vapply(unavailable, paste, "", collapse = ", "))[lengths(unavailable) > 0]),
    check_row(name, "The graph has no cycles", tryCatch({generation_order(ds); character()}, error = conditionMessage)),
    check_row(name, "Predictors are at the node's level or coarser",
      sprintf("%s (%s level) uses %s", sampled, ds$levels[sampled], vapply(finer, paste, "", collapse = ", "))[lengths(finer) > 0]),
    check_row(name, "Observation window dates come from DM or earlier datasets",
      setdiff(unlist(ds$window), c("", inputs, subject_date_nodes(study, name)))))
}

# ---- Formulas -------------------------------------------------------------------------

node_formula <- function(ds, variable, fit = NULL) {
  node <- ds$nodes[[variable]]
  predictors <- c(display_name(node$predictors), if (isTRUE(node$prev)) "previous value")
  by <- if (!is.null(ds$structure$test) && ds$levels[[variable]] == "record") paste(" | per", ds$structure$test)
  pins <- vapply(Filter(function(p) p$column == variable, ds$pins), pin_label, "")
  paste0(switch(node_type(ds, variable),
    key = if (variable == "USUBJID" && ds$name != "DM") "subject from DM" else record_structure_label(ds),
    rule = rule_label(ds$rules[[variable]]),
    identifier = "new identifier",
    blank = "not generated",
    sampled = if (ds$name == "DM" && identical(variable, arm_variable(ds))) paste(variable, "~ allocation ratio") else
      paste0(variable, " ~ ", if (length(predictors)) paste(predictors, collapse = " + ") else "1", by,
        if (!is.null(fit)) paste0(" · ", fit$description)),
    "not set"), if (length(pins)) paste0(" · ", pins, collapse = ""))
}

record_structure_label <- function(ds) {
  s <- ds$structure
  predictors <- if (length(s$predictors)) paste(display_name(s$predictors), collapse = " + ") else "1"
  switch(s$type,
    subject = "one record per subject",
    schedule = paste0("planned ", paste(s$keys, collapse = " × "), if (isTRUE(s$by_arm)) " by arm",
      if (!is.null(s$visit)) "; attendance per visit", if (!is.null(s$reach)) paste(" reached by", display_name(s$reach[["end"]])),
      if (isTRUE(s$sv)) "; visits from SV", if (length(ds$links$milestones))
        paste0("; a visit on ", paste(ifelse(ds$links$milestones %in% names(ds$links$milestone_visits),
          paste0(ds$links$milestones, " (visit ", ds$links$milestone_visits[ds$links$milestones], ")"), ds$links$milestones), collapse = ", "))),
    series = paste0("series of ", s$series, " per subject ~ ", predictors, "; each recorded at consecutive ", VISIT_HUB,
      " visits from a first visit until it stops"),
    count = paste0("records per subject ~ ", predictors))
}
